        .status-container::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: var(--secondary-bg);
            backdrop-filter: blur(15px);
            z-index: -1;
        }

        .status-container:hover {
            transform: translateY(-2px);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4),
                        0 0 0 1px rgba(79, 209, 199, 0.2);
        }

        .status-summary {
            padding: 15px 20px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: rgba(79, 209, 199, 0.05);
            transition: all 0.3s ease;
            user-select: none;
            border-bottom: 1px solid rgba(79, 209, 199, 0.1);
        }

        .status-summary:hover {
            background: var(--hover-bg);
        }

        .summary-left {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .character-avatar {
            width: 50px;
            height: 50px;
            background: var(--tag-bg);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--accent-color);
            font-size: 24px;
            border: 2px solid var(--tag-border);
            overflow: hidden;
            position: relative;
        }

        .character-avatar img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 50%;
        }

        .summary-info {
            color: var(--text-primary);
        }

        .character-name {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 5px;
            color: var(--text-primary);
        }

        .quick-status {
            font-size: 14px;
            color: var(--text-secondary);
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .expand-icon {
            color: var(--accent-color);
            font-size: 20px;
            transition: transform 0.3s ease;
        }

        .status-details[open] .expand-icon {
            transform: rotate(180deg);
        }

        .status-content {
            padding: 0;
            max-height: 0;
            overflow: hidden;
            transition: all 0.4s ease;
        }

        .status-details[open] .status-content {
            min-height: 70vh;
            padding: 20px;
            overflow-y: auto;
            overflow-x: hidden;
        }

        /* 自定义滚动条样式 */
        .status-content::-webkit-scrollbar {
            width: 6px;
        }

        .status-content::-webkit-scrollbar-track {
            background: rgba(79, 209, 199, 0.1);
            border-radius: 3px;
        }

        .status-content::-webkit-scrollbar-thumb {
            background: var(--accent-color);
            border-radius: 3px;
        }

        .status-content::-webkit-scrollbar-thumb:hover {
            background: var(--accent-secondary);
        }

        /* 优化后的时间区域 - toast 样式 */
        .time-section {
            width: 100%;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            background: var(--card-bg);
            border-radius: 25px;
            padding: 10px 16px;
            margin-bottom: 20px;
            color: var(--text-primary);
            font-size: 13px;
            font-weight: 500;
            backdrop-filter: blur(15px);
            border: 1px solid var(--tag-border);
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
        }

        .time-icon {
            font-size: 14px;
            color: var(--accent-color);
        }

        .time-content {
            display: flex;
            align-items: center;
            gap: 8px;
            flex-wrap: wrap;
        }

        .time-tag {
            border-radius: 12px;
            font-size: 11px;
            font-weight: 500;
            color: var(--text-primary);
        }

        /* 角色区域 - 左右布局 */
        .character-area {
            display: grid;
            grid-template-columns: auto 1fr;
            gap: 20px;
            align-items: center;
            margin-bottom: 20px;
            padding: 20px;
            background: var(--card-bg);
            border-radius: 15px;
            border: 1px solid rgba(79, 209, 199, 0.15);
        }

        .character-portrait {
            width: 120px;
            height: 160px;
            background: var(--tag-bg);
            border-radius: 15px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--accent-color);
            font-size: 48px;
            border: 2px solid var(--tag-border);
            transition: all 0.3s ease;
            overflow: hidden;
            position: relative;
        }

        .character-portrait:hover {
            background: rgba(79, 209, 199, 0.25);
            transform: scale(1.02);
            border-color: var(--accent-color);
        }

        .character-portrait img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 13px;
        }

        .character-info {
            display: flex;
            flex-direction: column;
            gap: 12px;
            min-height: 160px;
            justify-content: center;
        }

        /* Tag 样式 */
        .character-tag {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            border-radius: 20px;
            padding: 8px 12px;
            color: var(--text-primary);
            font-size: 12px;
            font-weight: 500;
            transition: all 0.3s ease;
            margin: 3px;
            background: var(--tag-bg);
            backdrop-filter: blur(10px);
            border: 1px solid var(--tag-border);
        }

        .character-tag:hover {
            background: rgba(79, 209, 199, 0.3);
            transform: translateY(-1px);
            border-color: var(--accent-color);
        }

        .tag-icon {
            font-size: 11px;
            color: var(--accent-color);
        }

        /* 标准信息项样式（用于具体位置等） */
        .character-info-item {
            background: rgba(45, 55, 72, 0.4);
            border-radius: 10px;
            padding: 12px;
            color: var(--text-primary);
            transition: all 0.3s ease;
            border: 1px solid rgba(79, 209, 199, 0.1);
        }

        .character-info-item:hover {
            background: rgba(45, 55, 72, 0.6);
            transform: translateX(5px);
            border-color: var(--tag-border);
        }

        .character-info-label {
            display: flex;
            align-items: center;
            gap: 8px;
            font-weight: 500;
            margin-bottom: 6px;
            font-size: 13px;
            color: var(--text-secondary);
        }

        .character-info-value {
            font-size: 12px;
            color: var(--text-muted);
            line-height: 1.4;
            padding-left: 20px;
        }

        /* Tags 容器 */
        .character-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        /* 服装区域样式 */
        .outfit-section {
            background: var(--card-bg);
            border-radius: 15px;
            padding: 18px;
            margin-bottom: 20px;
            color: var(--text-primary);
            border: 1px solid rgba(79, 209, 199, 0.15);
        }

        .outfit-title {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 15px;
            font-weight: 600;
            margin-bottom: 15px;
            color: var(--text-primary);
        }

        .outfit-title i {
            color: var(--accent-color);
        }

        .outfit-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
        }

        .outfit-item {
            background: rgba(45, 55, 72, 0.4);
            border-radius: 12px;
            padding: 12px;
            transition: all 0.3s ease;
            border: 1px solid rgba(79, 209, 199, 0.1);
        }

        .outfit-item:hover {
            background: rgba(45, 55, 72, 0.6);
            transform: translateY(-2px);
            border-color: var(--tag-border);
        }

        .outfit-item-header {
            display: flex;
            align-items: center;
            gap: 8px;
            font-weight: 500;
            margin-bottom: 8px;
            font-size: 13px;
            color: var(--text-secondary);
        }

        .outfit-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 4px;
        }

        .outfit-tag {
            display: inline-block;
            background: var(--tag-bg);
            border-radius: 12px;
            padding: 4px 8px;
            font-size: 11px;
            font-weight: 500;
            transition: all 0.3s ease;
            border: 1px solid var(--tag-border);
            color: var(--text-primary);
        }

        .outfit-tag:hover {
            background: rgba(79, 209, 199, 0.3);
            transform: scale(1.05);
            border-color: var(--accent-color);
        }

        /* 其他状态信息网格 */
        .status-grid {
            display: grid;
            gap: 15px;
        }

        .status-item {
            background: var(--card-bg);
            border-radius: 12px;
            padding: 15px;
            color: var(--text-primary);
            transition: all 0.3s ease;
            border: 1px solid rgba(79, 209, 199, 0.15);
        }

        .status-item:hover {
            background: rgba(45, 55, 72, 0.8);
            transform: translateX(5px);
            border-color: var(--tag-border);
        }

        .status-label {
            display: flex;
            align-items: center;
            gap: 10px;
            font-weight: 500;
            margin-bottom: 8px;
            font-size: 14px;
            color: var(--text-secondary);
        }

        .status-value {
            font-size: 13px;
            color: var(--text-muted);
            line-height: 1.5;
            padding-left: 12px;
        }

        .icon {
            font-size: 16px;
            width: 20px;
            text-align: center;
            color: var(--accent-color);
        }

        .small-icon {
            font-size: 14px;
            width: 16px;
            text-align: center;
            color: var(--accent-color);
        }

        .mood-indicator {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            margin-left: 8px;
        }

        .mood-positive { background: #48bb78; }
        .mood-negative { background: #f56565; }
        .mood-neutral { background: #ed8936; }
        .mood-complex { 
            background: linear-gradient(45deg, #f56565, #ed8936); 
        }

        .empty-state {
            text-align: center;
            padding: 40px 20px;
            color: var(--text-muted);
            font-style: italic;
            background: var(--card-bg);
            border-radius: 15px;
            border: 1px solid var(--tag-border);
        }

        /* 响应式设计 */
        @media (max-width: 400px) {
            .status-container {
                margin: 10px auto;
            }

            .status-summary {
                padding: 15px;
            }

            .status-details[open] .status-content {
                padding: 15px;
                min-height: 40vh;
            }

            .character-area {
                padding: 15px;
                gap: 15px;
            }

            .outfit-grid {
                grid-template-columns: 1fr;
            }

            .time-content {
                justify-content: center;
            }

            .character-area{
                flex-direction: column;
            }

            .character-area{
                display: none;
            }
        }

        /* 动画效果 */
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes fadeInLeft {
            from {
                opacity: 0;
                transform: translateX(-10px);
            }
            to {
                opacity: 1;
                transform: translateX(0);
            }
        }

        @keyframes fadeInScale {
            from {
                opacity: 0;
                transform: scale(0.8);
            }
            to {
                opacity: 1;
                transform: scale(1);
            }
        }

        @keyframes slideInRight {
            from {
                opacity: 0;
                transform: translateX(20px);
            }
            to {
                opacity: 1;
                transform: translateX(0);
            }
        }

        .status-item, .character-info-item, .outfit-item {
            animation: fadeInUp 0.3s ease forwards;
        }

        .character-tag {
            animation: fadeInLeft 0.3s ease forwards;
        }

        .outfit-tag {
            animation: fadeInScale 0.3s ease forwards;
        }

        .time-section {
            animation: slideInRight 0.4s ease forwards;
        }

        .character-tag:nth-child(1) { animation-delay: 0.1s; }
        .character-tag:nth-child(2) { animation-delay: 0.15s; }

        .character-info-item:nth-child(2) { animation-delay: 0.2s; }

        .outfit-item:nth-child(1) { animation-delay: 0.25s; }
        .outfit-item:nth-child(2) { animation-delay: 0.3s; }
        .outfit-item:nth-child(3) { animation-delay: 0.35s; }
        .outfit-item:nth-child(4) { animation-delay: 0.4s; }

        .status-item:nth-child(1) { animation-delay: 0.45s; }
        .status-item:nth-child(2) { animation-delay: 0.5s; }
        .status-item:nth-child(3) { animation-delay: 0.55s; }
        .status-item:nth-child(4) { animation-delay: 0.6s; }
    </style>
</head>
<body>
    <div class="status-container">
        <details class="status-details" id="statusDetails">
            <summary class="status-summary">
                <div class="summary-left">
                    <div class="character-avatar" id="characterAvatar">
                        <i class="fas fa-user"></i>
                    </div>
                    <div class="summary-info">
                        <div class="character-name" id="characterName">角色状态</div>
                        <div class="quick-status" id="quickStatus">
                            <i class="fas fa-clock"></i>
                            <span>点击展开详细信息</span>
                        </div>
                    </div>
                </div>
                <i class="fas fa-chevron-down expand-icon"></i>
            </summary>

            <div class="status-content">
                <!-- 时间信息 - toast 样式 -->
                <div class="time-section" id="timeSection">
                    <i class="fas fa-clock time-icon"></i>
                    <div class="time-content" id="timeContent">
                        <span>暂无时间信息</span>
                    </div>
                </div>

                <!-- 角色区域 -->
                <div class="character-area">
                    <div class="character-portrait" id="characterPortrait">
                        <i class="fas fa-user-circle"></i>
                    </div>

                    <div class="character-info" id="characterInfo">
                        <!-- 角色信息将动态生成 -->
                    </div>
                </div>

                <!-- 服装区域 -->
                <div class="outfit-section" id="outfitSection" style="display: none;">
                    <div class="outfit-title">
                        <i class="fas fa-tshirt"></i>
                        <span>穿着搭配</span>
                    </div>
                    <div class="outfit-grid" id="outfitGrid">
                        <!-- 服装信息将动态生成 -->
                    </div>
                </div>

                <!-- 其他状态信息 -->
                <div class="status-grid" id="statusGrid">
                    <!-- 其他状态信息将动态生成 -->
                </div>
            </div>
        </details>
    </div>

    <div class="empty-state" id="emptyState" style="display: none;">
        <i class="fas fa-info-circle" style="font-size: 24px; margin-bottom: 10px; display: block;"></i>
        暂无状态信息
    </div>

    <script>
        // 这里是SillyTavern的正则捕获到的数据
        const chatData = `

`;

        console.log('角色卡数据:', chatData);

        // 差分立绘配置
        const charImg = {
            '全裸': 'https://files.catbox.moe/cl03gs.png',
            '半裸': 'https://files.catbox.moe/8hwlvu.png',
            '内衣': 'https://files.catbox.moe/f580gt.png',
            '正常': 'https://files.catbox.moe/r92uxf.png',
            'default': 'https://files.catbox.moe/rbhqri.png',
        };

        // 状态项配置：定义每种状态对应的图标
        const statusConfig = {
            '登场角色': { icon: 'fas fa-user-tag' },
            '地点': { icon: 'fas fa-map-marker-alt' },
            '具体位置': { icon: 'fas fa-location-dot' },
            '上衣': { icon: 'fas fa-tshirt' },
            '下装': { icon: 'fas fa-user-tie' },
            '足部': { icon: 'fas fa-shoe-prints' },
            '配饰': { icon: 'fas fa-gem' },
            '当前动作': { icon: 'fas fa-running' },
            '情绪': { icon: 'fas fa-heart' },
            '想法': { icon: 'fas fa-brain' },
            '心情': { icon: 'fas fa-smile' },
            '状态': { icon: 'fas fa-circle-info' }
        };

        // 定义需要放在角色信息区域的项目
        const characterInfoKeys = ['登场角色', '地点', '具体位置'];

        // 定义使用 tag 样式的项目
        const tagStyleKeys = ['登场角色', '地点'];

        // 定义服装相关的项目
        const outfitKeys = ['上衣', '下装', '足部', '配饰'];

        // 解析角色信息和状态
        function parseCharacterInfo(characterText) {
            // 匹配格式：角色名[状态] 或者 角色名
            const match = characterText.match(/^(.+?)\[(.+?)\]$/) || characterText.match(/^(.+)$/);

            if (match) {
                if (match[2]) {
                    // 有状态信息
                    return {
                        name: match[1].trim(),
                        status: match[2].trim()
                    };
                } else {
                    // 没有状态信息
                    return {
                        name: match[1].trim(),
                        status: null
                    };
                }
            }

            return {
                name: characterText,
                status: null
            };
        }

        // 获取角色图片URL
        function getCharacterImage(status) {
            if (status && charImg[status]) {
                return charImg[status];
            }

            if (charImg['default']) {
                return charImg['default'];
            }

            return null;
        }

        // 更新角色图片
        function updateCharacterImage(element, imageUrl, fallbackIcon = 'fas fa-user') {
            if (imageUrl) {
                // 如果有图片，创建img元素
                const img = document.createElement('img');
                img.src = imageUrl;
                img.onerror = function() {
                    // 图片加载失败，回退到图标
                    element.innerHTML = `<i class="${fallbackIcon}"></i>`;
                };
                element.innerHTML = '';
                element.appendChild(img);
            } else {
                // 没有图片，使用图标
                element.innerHTML = `<i class="${fallbackIcon}"></i>`;
            }
        }

        // 情绪分析函数
        function analyzeMood(text) {
            if (!text) return 'neutral';

            const positiveWords = ['开心', '高兴', '愉快', '兴奋', '满足', '舒适', '温柔'];
            const negativeWords = ['难过', '生气', '愤怒', '沮丧', '焦虑', '紧张', '不安', '复杂'];

            const hasPositive = positiveWords.some(word => text.includes(word));
            const hasNegative = negativeWords.some(word => text.includes(word));

            if (hasPositive && hasNegative) return 'complex';
            if (hasPositive) return 'positive';
            if (hasNegative) return 'negative';
            return 'neutral';
        }

        // 解析状态数据
        function parseStatusData(data) {
            if (!data || data.trim() === '') {
                return null;
            }

            const lines = data.trim().split('\n').filter(line => line.trim());
            const result = {
                time: '',
                character: '',
                characterStatus: null,
                characterInfo: [],
                outfitItems: [],
                otherItems: []
            };

            for (const line of lines) {
                const trimmedLine = line.trim();

                // 解析时间信息 [时间格式]
                if (trimmedLine.startsWith('[') && trimmedLine.endsWith(']')) {
                    result.time = trimmedLine.slice(1, -1);
                    continue;
                }

                // 解析键值对格式的信息
                const colonIndex = trimmedLine.indexOf(':');
                if (colonIndex > 0) {
                    const key = trimmedLine.substring(0, colonIndex).trim();
                    const value = trimmedLine.substring(colonIndex + 1).trim();

                    if (key === '登场角色') {
                        const characterInfo = parseCharacterInfo(value);
                        result.character = characterInfo.name;
                        result.characterStatus = characterInfo.status;

                        // 存储处理后的角色信息（只包含角色名，不包含状态）
                        const item = { key, value: characterInfo.name };
                        result.characterInfo.push(item);
                    } else {
                        const item = { key, value };

                        // 根据键名分类
                        if (characterInfoKeys.includes(key)) {
                            result.characterInfo.push(item);
                        } else if (outfitKeys.includes(key)) {
                            result.outfitItems.push(item);
                        } else {
                            result.otherItems.push(item);
                        }
                    }
                }
            }

            return result;
        }

        // 解析服装标签
        function parseOutfitTags(value) {
            return value.split('+').map(tag => tag.trim()).filter(tag => tag.length > 0);
        }

        // 渲染状态界面
        function renderStatus(statusData) {
            const container = document.querySelector('.status-container');
            const emptyState = document.getElementById('emptyState');

            if (!statusData) {
                container.style.display = 'none';
                emptyState.style.display = 'block';
                return;
            }

            container.style.display = 'block';
            emptyState.style.display = 'none';

            // 更新角色名称
            const characterName = document.getElementById('characterName');
            characterName.textContent = statusData.character || '未知角色';

            // 获取并更新角色图片
            const characterImageUrl = getCharacterImage(statusData.characterStatus);

            // 更新头像（summary区域）
            const characterAvatar = document.getElementById('characterAvatar');
            updateCharacterImage(characterAvatar, characterImageUrl, 'fas fa-user');

            // 更新立绘（详情区域）
            const characterPortrait = document.getElementById('characterPortrait');
            updateCharacterImage(characterPortrait, characterImageUrl, 'fas fa-user-circle');

            // 更新快速状态
            const quickStatus = document.getElementById('quickStatus');
            const locationItem = statusData.characterInfo.find(item => item.key === '地点');
            if (locationItem) {
                quickStatus.innerHTML = `
                    <i class="fas fa-map-marker-alt"></i>
                    <span>${locationItem.value}</span>
                `;
            }

            // 更新时间信息 - toast 样式
            const timeContent = document.getElementById('timeContent');
            // if (statusData.time) {
            //     const timeElements = statusData.time.split(' - ').map(item => 
            //         `<span class="time-tag">${item.trim()}</span>`
            //     ).join('');
            //     timeContent.innerHTML = timeElements;
            // } else {
            //     timeContent.innerHTML = '<span>暂无时间信息</span>';
            // }
            // console.log("[debug]timeData:", statusData.time);
            if (statusData.time) {
                const timeElements =  `<span class="time-tag">『 ${statusData.time} 』</span>`;
                timeContent.innerHTML = timeElements;
            } else {
                timeContent.innerHTML = '<span>暂无时间信息</span>';
            }

            // 生成角色信息区域
            const characterInfo = document.getElementById('characterInfo');
            characterInfo.innerHTML = '';

            // 分离 tag 样式和普通样式的项目
            const tagItems = statusData.characterInfo.filter(item => tagStyleKeys.includes(item.key));
            const regularItems = statusData.characterInfo.filter(item => !tagStyleKeys.includes(item.key));

            // 如果有 tag 项目，创建 tags 容器
            if (tagItems.length > 0) {
                const tagsContainer = document.createElement('div');
                tagsContainer.className = 'character-tags';

                tagItems.forEach((item, index) => {
                    const config = statusConfig[item.key] || { icon: 'fas fa-info' };

                    const tagElement = document.createElement('div');
                    tagElement.className = 'character-tag';
                    tagElement.style.animationDelay = `${(index + 1) * 0.05}s`;

                    tagElement.innerHTML = `
                        <i class="${config.icon} tag-icon"></i>
                        <span>${item.value}</span>
                    `;

                    tagsContainer.appendChild(tagElement);
                });

                characterInfo.appendChild(tagsContainer);
            }

            // 添加普通样式的项目
            regularItems.forEach((item, index) => {
                const config = statusConfig[item.key] || { icon: 'fas fa-info' };

                const infoElement = document.createElement('div');
                infoElement.className = 'character-info-item';
                infoElement.style.animationDelay = `${(tagItems.length + index + 1) * 0.05}s`;

                infoElement.innerHTML = `
                    <div class="character-info-label">
                        <i class="${config.icon} small-icon"></i>
                        <span>${item.key}</span>
                    </div>
                    <div class="character-info-value">${item.value}</div>
                `;

                characterInfo.appendChild(infoElement);
            });

            // 生成服装区域
            const outfitSection = document.getElementById('outfitSection');
            const outfitGrid = document.getElementById('outfitGrid');

            if (statusData.outfitItems.length > 0) {
                outfitSection.style.display = 'block';
                outfitGrid.innerHTML = '';

                statusData.outfitItems.forEach((item, index) => {
                    const config = statusConfig[item.key] || { icon: 'fas fa-info' };
                    const tags = parseOutfitTags(item.value);

                    const outfitElement = document.createElement('div');
                    outfitElement.className = 'outfit-item';
                    outfitElement.style.animationDelay = `${(index + 1) * 0.05}s`;

                    const tagsHtml = tags.map(tag => 
                        `<span class="outfit-tag">${tag}</span>`
                    ).join('');

                    outfitElement.innerHTML = `
                        <div class="outfit-item-header">
                            <i class="${config.icon} small-icon"></i>
                            <span>${item.key}</span>
                        </div>
                        <div class="outfit-tags">
                            ${tagsHtml}
                        </div>
                    `;

                    outfitGrid.appendChild(outfitElement);
                });
            } else {
                outfitSection.style.display = 'none';
            }

            // 生成其他状态网格
            const statusGrid = document.getElementById('statusGrid');
            statusGrid.innerHTML = '';

            statusData.otherItems.forEach((item, index) => {
                const config = statusConfig[item.key] || { icon: 'fas fa-info' };
                const mood = item.key === '情绪' ? analyzeMood(item.value) : null;

                const statusElement = document.createElement('div');
                statusElement.className = 'status-item';
                statusElement.style.animationDelay = `${(statusData.characterInfo.length + statusData.outfitItems.length + index + 1) * 0.05}s`;

                statusElement.innerHTML = `
                    <div class="status-label">
                        <i class="${config.icon} icon"></i>
                        <span>${item.key}</span>
                        ${mood ? `<span class="mood-indicator mood-${mood}"></span>` : ''}
                    </div>
                    <div class="status-value">${item.value}</div>
                `;

                statusGrid.appendChild(statusElement);
            });
        }

        // 初始化
        function init() {
            const statusData = parseStatusData(chatData);
            renderStatus(statusData);

            // 如果有数据，自动展开
            if (statusData && (statusData.characterInfo.length > 0 || statusData.outfitItems.length > 0 || statusData.otherItems.length > 0)) {
                document.getElementById('statusDetails').setAttribute('open', '');
            }
        }

        // 页面加载完成后初始化
        document.addEventListener('DOMContentLoaded', init);
    </script>
</body>
</html>
