<body>
    <div id="bubble-container">

    </div>
    <script>
        //接收正则替换的数据，示例：
        // 周雨欣|[照、照片吗？ (*ﾟ∀ﾟ*)/那个...先生想看什么样的照片呢？]
        // 陈明强|[我、我有很多制服，还有平时的衣服.../不过我不太知道什么样的比较好...]
        // 我方|[啊！对、对不起！我是不是应该直接发的？/作为新手，我真的不太懂这些规矩...]
        // 陈明强|[<voice>语音通话申请</voice>]
        // 陈明强|[<video>视频通话申请</video>]
        // 我方|[<accept>已接受通话</accept>]
        // 我方|[<reject>已拒绝通话</reject>]
        const bubbleMessage = `

`;
        console.log("[debug]bubbleMessage:", bubbleMessage);

        //DOM元素
        const bubbleContainer = document.getElementById("bubble-container");
        //定义我方和对方名称
        const selfName = ["我方", "周雨欣"];
        const otherName = ["陈明强"];

        function parseMessage(message){
            const result = [];

            const messageContent = message.trim();
            const lines = messageContent.split('\n').map(line => line.trim()).filter(line => line);

            lines.forEach(line => {
                const parts = line.split('|');
                const hasSender = parts.length === 2;
                const sender = hasSender ? parts[0].trim() : null;
                const content = hasSender ? parts[1].trim() : line;

                //解析消息
                let bubbles = [];

                // 提取 [xxx] 形式的内容
                const contentMatches = content.match(/\[(.*?)\]/g);
                if (contentMatches) {
                    let fullMessage = contentMatches.map(m => m.substring(1, m.length - 1)).join('');

                    // 检查是否包含特殊标签
                    const specialTags = ['voice', 'video', 'accept', 'reject'];
                    let hasSpecialTag = false;

                    for (let tag of specialTags) {
                        const tagRegex = new RegExp(`<${tag}>(.*?)</${tag}>`, 'gi');
                        const match = fullMessage.match(tagRegex);
                        if (match) {
                            hasSpecialTag = true;
                            const tagContent = match[0].replace(new RegExp(`</?${tag}>`, 'gi'), '');
                            bubbles.push({
                                type: tag,
                                text: tagContent.trim()
                            });
                            break; // 每个消息只处理一个特殊标签
                        }
                    }

                    // 如果没有特殊标签，按普通消息处理
                    if (!hasSpecialTag) {
                        const textBubbles = fullMessage.split('/').map(text => text.trim()).filter(text => text);
                        bubbles = textBubbles.map(text => ({
                            type: 'text',
                            text: text
                        }));
                    }
                }

                // 如果没有找到气泡内容，跳过
                if (bubbles.length === 0) return;

                // 添加消息到结果中
                console.log("[debug]当前发送者:", sender);
                console.log("[debug]当前消息:", bubbles);
                console.log("[debug]是否在发送者数组中:", selfName.includes(sender));
                result.push({
                    type: selfName.includes(sender) ? 'self' : 'other',
                    sender: sender,
                    contentType: 'mixed',
                    bubbles: bubbles
                });
            })
            return result;
        }

        // 获取消息类型对应的图标
        function getMessageIcon(messageType) {
            const icons = {
                'voice': 'fas fa-phone',
                'video': 'fas fa-video',
                'accept': 'fas fa-check-circle',
                'reject': 'fas fa-times-circle',
                'text': ''
            };
            return icons[messageType] || '';
        }

        // 创建气泡DOM元素
        function createBubbleElement(bubbleData) {
            const bubble = document.createElement('div');
            bubble.className = `bubble ${bubbleData.type}`;

            const iconClass = getMessageIcon(bubbleData.type);

            if (iconClass) {
                // 创建图标元素
                const icon = document.createElement('i');
                icon.className = `bubble-icon ${iconClass}`;
                bubble.appendChild(icon);
            }

            // 创建文本元素
            const textElement = document.createElement('span');
            textElement.className = 'bubble-text';
            textElement.textContent = bubbleData.text;
            bubble.appendChild(textElement);

            return bubble;
        }

        // 创建打字指示器
        function createTypingIndicator() {
            const indicator = document.createElement('div');
            indicator.className = 'typing-indicator';
            for (let i = 0; i < 3; i++) {
                const dot = document.createElement('div');
                dot.className = 'typing-dot';
                indicator.appendChild(dot);
            }
            return indicator;
        }

        // 渲染消息组
        function renderMessageGroup(messageData, delay = 0) {
            return new Promise((resolve) => {
                setTimeout(() => {
                    const messageGroup = document.createElement('div');
                    messageGroup.className = `message-group message-${messageData.type}`;

                    // 如果是对方消息，显示发送者名称
                    if (messageData.type === 'other') {
                        const senderName = document.createElement('div');
                        senderName.className = 'sender-name';
                        senderName.textContent = messageData.sender;
                        messageGroup.appendChild(senderName);
                    }

                    bubbleContainer.appendChild(messageGroup);

                    // 如果是对方消息，先显示打字指示器
                    if (messageData.type === 'other') {
                        const typingIndicator = createTypingIndicator();
                        messageGroup.appendChild(typingIndicator);

                        // 1秒后移除打字指示器并开始显示气泡
                        setTimeout(() => {
                            messageGroup.removeChild(typingIndicator);
                            renderBubbles(messageGroup, messageData.bubbles, 0);
                            resolve();
                        }, 1000);
                    } else {
                        // 我方消息直接显示气泡
                        renderBubbles(messageGroup, messageData.bubbles, 0);
                        resolve();
                    }
                }, delay);
            });
        }

        // 渲染气泡
        function renderBubbles(container, bubbles, bubbleDelay = 0) {
            bubbles.forEach((bubbleData, index) => {
                setTimeout(() => {
                    const bubble = createBubbleElement(bubbleData);
                    bubble.style.animationDelay = `${index * 0.1}s`;
                    container.appendChild(bubble);

                    // 滚动到底部
                    setTimeout(() => {
                        bubbleContainer.scrollTop = bubbleContainer.scrollHeight;
                    }, 300);
                }, index * 500 + bubbleDelay); // 每个气泡间隔500ms
            });
        }

        // 渲染所有消息
        async function renderAllMessages(bubbleDataArray) {
            for (let i = 0; i < bubbleDataArray.length; i++) {
                await renderMessageGroup(bubbleDataArray[i], i * 200);
                // 等待当前消息组的所有气泡都显示完成
                await new Promise(resolve => {
                    const bubbleCount = bubbleDataArray[i].bubbles.length;
                    const totalDelay = (bubbleCount - 1) * 500 + 1000; // 最后一个气泡延迟 + 额外等待时间
                    setTimeout(resolve, totalDelay);
                });
            }
        }

        // 页面加载完成后初始化
        document.addEventListener("DOMContentLoaded", function() {
            if (bubbleMessage) {
                const bubbleData = parseMessage(bubbleMessage);
                console.log("[debug]bubbleData:", bubbleData);
                renderAllMessages(bubbleData);
            }
        });
    </script>
</body>
</html>
