    <meta charset="UTF-8">
    <!-- 引入FontAwesome图标库 -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Microsoft YaHei', Arial, sans-serif;
            background-color: transparent;
            padding: 0 20px;
        }

        #bubble-container {
            max-width: 600px;
            margin: 0 auto;
            background-color: transparent;
            padding: 10px;
        }

        .message-group {
            margin-bottom: 15px;
        }

        .sender-name {
            font-size: 12px;
            color: #999;
            margin-bottom: 5px;
            padding-left: 5px;
        }

        .bubble {
            max-width: 70%;
            padding: 10px 15px;
            border-radius: 18px;
            margin: 5px 0;
            word-wrap: break-word;
            opacity: 0;
            transform: translateY(10px);
            animation: bubbleSlideIn 0.3s ease-out forwards;
            box-shadow: 0 1px 2px rgba(0,0,0,0.1);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        /* 普通文本消息样式 */
        .message-self .bubble.text {
            background-color: #007AFF;
            color: white;
            margin-left: auto;
            margin-right: 0;
        }

        .message-other .bubble.text {
            background-color: #E5E5EA;
            color: #000;
            margin-left: 0;
            margin-right: auto;
        }

        /* 语音通话样式 */
        .bubble.voice {
            background: linear-gradient(135deg, #4CAF50, #45a049);
            color: white;
            animation: bubbleSlideIn 0.3s ease-out forwards, callPulse 2s infinite;
        }

        /* 视频通话样式 */
        .bubble.video {
            background: linear-gradient(135deg, #2196F3, #1976D2);
            color: white;
            animation: bubbleSlideIn 0.3s ease-out forwards, callPulse 2s infinite;
        }

        /* 接受通话样式 */
        .bubble.accept {
            background: linear-gradient(135deg, #4CAF50, #2E7D32);
            color: white;
            animation: bubbleSlideIn 0.3s ease-out forwards, successBlink 1s ease-out;
        }

        /* 拒绝通话样式 */
        .bubble.reject {
            background: linear-gradient(135deg, #f44336, #d32f2f);
            color: white;
            animation: bubbleSlideIn 0.3s ease-out forwards, errorShake 0.5s ease-out;
        }

        .message-self {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
        }

        .message-other {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
        }

